export function solve(capacity, ops) {
  const m = new Map();
  const out = [];

  for (const [op, k, v] of ops) {
    if (op === "get") {
      if (m.has(k)) {
        const value = m.get(k);
        m.delete(k);
        m.set(k, value);
        out.push(value);
      } else {
        out.push(-1);
      }
    } else {
      m.delete(k);
      m.set(k, v);
      if (m.size > capacity) {
        m.delete(m.keys().next().value);
      }
    }
  }

  return out;
}
```

The restored invariant is that Map iteration order runs from least recently used to most recently used. Successful gets and all puts move the key to the end; misses leave recency unchanged, and overflow evicts the first key. This remains a synchronous, dependency-free ES module with the same `solve(capacity, ops)` API; no other files need changes.

